query LISTING_QUERY(
  $widgetId: ID!
  $host: String
  $page: Int
  $filters: [JobAdFilter!]!
  $useExampleData: Boolean!
  $rps: Int
) {
  widget(
    id: $widgetId
    host: $host
    useExampleData: $useExampleData
  ) {
    config { languageIso }
    jobAdList(page: $page, filters: $filters, rps: $rps) {
      paginator {
        currentPage
        lastPage
        totalNumberOfItems
        numberOfItemsPerPage
      }
      groupedJobAds {
        ...jobAdGroup
        groups {
          ...jobAdGroup
          groups {
            ...jobAdGroup
            groups {
              ...jobAdGroup
            }
          }
        }
      }
    }
  }
}

fragment jobAdGroup on JobAdGroup {
  jobAds {
    id
    title
    validFrom
    languageIso
    teaser
    locations {
      country
      region
      district
      city
      cityPart
    }
    salary {
      min
      max
      period
      currency
    }
    employer { companyName }
    parameters {
      employmentTypesObjects { id label }
    }
    fieldsObjects { id label }
    professionsObjects { id label }
  }
}

query JOB_DETAIL(
  $widgetId: ID!
  $host: String
  $useExampleData: Boolean!
  $jobId: ID!
) {
  widget(id: $widgetId, host: $host, useExampleData: $useExampleData) {
    jobAd(id: $jobId) {
      id
      languageIso
      content { htmlContent }
    }
  }
}

